using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using Mewgic;using Mewgic.Core;using Mewgic.Map;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;
[InitializeOnLoad]public static class MapProgressionTests
{
 static readonly List<string> checks=new List<string>();static readonly Queue<Action> actions=new Queue<Action>();static double next;static string original;static bool hadOriginal;
 static MapProgressionTests(){EditorApplication.update+=Tick;}
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks.Add(name);}
 static ProgressLedger Memory(ProgressData d=null)=>new ProgressLedger(d??new ProgressData(),_=>{});
 static void CheckThrows(Action a,string name){try{a();}catch(ArgumentException){Check(true,name);return;}throw new Exception(name);}
 public static void Models()
 {
  var data=MapProgressionCatalog.Definition();var ledger=Memory();var map=new MapProgression(data,ledger,MapProgressionCatalog.Verified);
  Check(MapProgressionCatalog.Verified(1)&&MapProgressionCatalog.Verified(2)&&!MapProgressionCatalog.Verified(3),"Only two existing runtime levels verify");
  foreach(int id in new[]{1,2}){var level=GameplayLevelCatalog.Load(id);var p=new Puzzle(level.Bottles);var solution=PuzzleSolver.Solve(p.Export());foreach(var m in solution.Moves)Check(p.Pour(m.Source,m.Target)>0,"Verified catalog move "+id);Check(p.Won,"Catalog solution really wins "+id);}
  Check(map.CurrentId==1&&map.CanEnter(1)&&!map.CanEnter(2)&&!map.CanEnter(3),"New profile sequential gate");Check(!GameplayLevelCatalog.Select(2,ledger)&&GameplayLevelCatalog.SelectedId==1,"Catalog rejects locked selection");
  Check(!map.ClaimChest(0,out _)&&ledger.Remaining(BoosterKind.Hint)==3,"Chest cannot award early");
  ledger.Claim(1,2,true,out _);Check(map.CanEnter(1)&&map.CanEnter(2)&&map.CurrentId==2&&map.Stars(1)==2,"Completed replay, next unlock and best stars");ledger.Claim(1,1,true,out _);Check(map.Stars(1)==2,"Lower replay never downgrades stars");ledger.Claim(1,3,true,out _);Check(map.Stars(1)==3,"Better replay raises best stars");
  ledger.Claim(2,3,true,out _);Check(map.RegionComplete(0)&&map.Completed(0)==2&&map.Total(0)==2&&map.CurrentId==0,"Village completes exactly two real levels");Check(!map.RegionOpen(1)&&!map.CanEnter(3),"Missing levels do not unlock after village victory");int balance=ledger.Remaining(BoosterKind.Hint);Check(map.ClaimChest(0,out bool granted)&&granted&&ledger.Remaining(BoosterKind.Hint)==balance+1,"Milestone awards real hint");Check(map.ClaimChest(0,out granted)&&!granted&&ledger.Remaining(BoosterKind.Hint)==balance+1,"Double chest claim cannot duplicate award");
  var reloaded=new MapProgression(data,Memory(JsonUtility.FromJson<ProgressData>(JsonUtility.ToJson(ledger.Snapshot))),MapProgressionCatalog.Verified);Check(reloaded.ChestClaimed(0)&&reloaded.Stars(1)==3&&!reloaded.ChestReady(0),"Stars and claimed chest survive JSON reload");
  var legacy=JsonUtility.FromJson<ProgressData>("{\"version\":1,\"undo\":2,\"hint\":7,\"extra\":1,\"shuffle\":1,\"levels\":[{\"level\":1,\"bestStars\":2,\"rewardClaimed\":true}]}");var old=Memory(legacy);Check(old.Completed(1)&&old.BestStars(1)==2&&old.Remaining(BoosterKind.Hint)==7&&!old.MilestoneClaimed("map.village.v1"),"Old v1 saves migrate without losing balance or stars");
  var failedData=ledger.Snapshot;failedData.claimedMilestones.Clear();var failed=new ProgressLedger(failedData,_=>throw new IOException("test write failure"));int oldBalance=failed.Remaining(BoosterKind.Hint);Check(!new MapProgression(data,failed,MapProgressionCatalog.Verified).ClaimChest(0,out granted)&&!granted&&failed.Remaining(BoosterKind.Hint)==oldBalance&&!failed.MilestoneClaimed("map.village.v1"),"Save failure leaves reward and idempotency marker unchanged");
  var overflow=ledger.Snapshot;overflow.claimedMilestones.Clear();overflow.hint=int.MaxValue;var full=Memory(overflow);Check(!new MapProgression(data,full,MapProgressionCatalog.Verified).ClaimChest(0,out granted)&&!granted&&!full.MilestoneClaimed("map.village.v1"),"Reward overflow safely rejected");
  var orphan=Memory();orphan.Claim(2,3,true,out _);Check(!new MapProgression(data,orphan,MapProgressionCatalog.Verified).CanEnter(2),"Out of order imported result cannot bypass prerequisite");orphan.Claim(3,3,true,out _);Check(!new MapProgression(data,orphan,MapProgressionCatalog.Verified).CanEnter(3),"Saved unknown result cannot validate a missing level");
  var isolatedRegion=Memory();foreach(int id in new[]{3,4,5})isolatedRegion.Claim(id,3,true,out _);var isolatedMap=new MapProgression(data,isolatedRegion,id=>id>0&&id<=11);Check(!isolatedMap.ChestReady(1)&&!isolatedMap.ClaimChest(1,out _),"Out of order completed region cannot claim milestone");
  var all=Memory();var synthetic=new MapProgression(data,all,id=>id>0&&id<=11);for(int id=1;id<=11;id++){for(int later=id+1;later<=11;later++)Check(!synthetic.CanEnter(later),"Synthetic later level locked "+id+"/"+later);Check(synthetic.CanEnter(id),"Synthetic sequential region transition "+id);all.Claim(id,id%3+1,true,out _);Check(synthetic.CanEnter(id),"Synthetic completed replay "+id);}for(int r=0;r<4;r++)Check(synthetic.RegionOpen(r)&&synthetic.RegionComplete(r),"Synthetic region completion "+r);
  var invalid=MapProgressionCatalog.Definition();invalid.regions[1].levels[0]=1;CheckThrows(()=>new MapProgression(invalid,Memory(),_=>true),"Duplicate level mapping rejected");
  invalid=MapProgressionCatalog.Definition();invalid.regions[1].reward.id=invalid.regions[0].reward.id;CheckThrows(()=>new MapProgression(invalid,Memory(),_=>true),"Duplicate milestone identifiers rejected");
  string key="Mewgic.Tests.Part06B."+Guid.NewGuid().ToString("N");try{var disk=GameplayProgress.Open(key);disk.Claim(1,2,true,out _);disk.Claim(2,3,true,out _);var diskMap=new MapProgression(data,disk,MapProgressionCatalog.Verified);Check(diskMap.ClaimChest(0,out granted)&&granted,"Real PlayerPrefs milestone save");int saved=disk.Remaining(BoosterKind.Hint);var again=GameplayProgress.Open(key);Check(again.BestStars(1)==2&&again.MilestoneClaimed("map.village.v1")&&new MapProgression(data,again,MapProgressionCatalog.Verified).ClaimChest(0,out granted)&&!granted&&again.Remaining(BoosterKind.Hint)==saved,"Actual disk reload preserves stars and prevents repeat chest");}finally{PlayerPrefs.DeleteKey(key);PlayerPrefs.Save();}
 }
 static MapWorld W=>UnityEngine.Object.FindFirstObjectByType<MapWorld>();static Puzzle Model()=>(Puzzle)typeof(PrototypeApp).GetField("puzzle",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(UnityEngine.Object.FindFirstObjectByType<PrototypeApp>());
 static void Click(string name){Canvas.ForceUpdateCanvases();var g=GameObject.Find(name);Check(g!=null,"UI exists "+name);var r=(RectTransform)g.transform;var d=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(d,hits);Check(hits.Count>0&&hits[0].gameObject==g,"Real top raycast "+name);ExecuteEvents.Execute(g,d,ExecuteEvents.pointerClickHandler);}
 static void Add(Action action)=>actions.Enqueue(action);static void Tap(string name)=>Add(()=>Click(name));
 static void Solve(int id){foreach(var move in PuzzleSolver.Solve(GameplayLevelCatalog.Load(id).Bottles).Moves){int s=move.Source,t=move.Target;Tap("Bottle "+(s+1));Tap("Bottle "+(t+1));}}
 public static void Run()
 {
  if(EditorApplication.isPlaying)throw new Exception("Stop Play first");checks.Clear();actions.Clear();GameplayLevelCatalog.ResetSelection();Models();hadOriginal=PlayerPrefs.HasKey(GameplayProgress.StorageKey);original=PlayerPrefs.GetString(GameplayProgress.StorageKey,"");GameplayProgress.UseTestProfile();
  Add(()=>{Check(W.Progression.CurrentId==1,"Fresh map current level 1");Check(GameObject.Find("LevelSlot_0_0/LevelNumber").GetComponent<TMPro.TMP_Text>().text=="1","Real numbered node");ScreenCapture.CaptureScreenshot("C:/Dev/Mewgic/docs/PART06B_INITIAL_GAMEVIEW.png");});Tap("LevelSlot_0_1");Add(()=>Check(W.InformationVisible&&UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="LevelMap","Locked level2 cannot enter"));Tap("MapInfoClose");Tap("LevelSlot_0_0");
  Add(()=>Check(GameplayLevelCatalog.SelectedId==1&&GameplayLevelCatalog.FromMap&&Model().Count==4,"Map launches real level1"));Solve(1);
  Add(()=>Check(Model().Won&&GameplayProgress.Current.Completed(1)&&GameplayProgress.Current.BestStars(1)==3,"Real win stores three stars"));Tap("ResultHome");
  Add(()=>{Check(W.Progression.CurrentId==2&&W.Progression.Status(0,0)==MapLevelStatus.Completed&&W.Progression.Status(0,1)==MapLevelStatus.Current,"Return map updates completion and current highlight");Check(GameObject.Find("LevelSlot_0_0").GetComponent<MapNodeBadge>().Stars==3,"Visible stars match saved best");ScreenCapture.CaptureScreenshot("C:/Dev/Mewgic/docs/PART06B_PROGRESS_GAMEVIEW.png");});Tap("LevelSlot_0_0");Add(()=>Check(Model().Moves==0&&GameplayLevelCatalog.SelectedId==1,"Completed level replay starts clean"));Tap("Home");Tap("LevelSlot_0_1");
  Add(()=>Check(Model().Count==5&&GameplayLevelCatalog.SelectedId==2,"Unlocked level2 has real five bottles"));Solve(2);Add(()=>Check(Model().Won&&GameplayProgress.Current.Completed(2),"Real second victory completes village"));Tap("ResultHome");
  Add(()=>Check(W.Progression.RegionComplete(0)&&W.Progression.ChestReady(0)&&!W.Progression.RegionOpen(1),"Village milestone ready; unverified next region stays closed"));Tap("Chest_0_0");Tap("ClaimMapChest");
  Add(()=>{Check(W.Progression.ChestClaimed(0)&&GameplayProgress.Current.Remaining(BoosterKind.Hint)==6,"Actual milestone click awards exactly once");Check(!GameObject.Find("ClaimMapChest"),"Claim button hidden after success");});Tap("MapInfoClose");Tap("Chest_0_0");Add(()=>Check(!GameObject.Find("ClaimMapChest")&&GameplayProgress.Current.Remaining(BoosterKind.Hint)==6,"Repeated chest click cannot award"));Tap("MapInfoClose");
  Add(()=>ScreenCapture.CaptureScreenshot("C:/Dev/Mewgic/docs/PART06B_COMPLETED_GAMEVIEW.png"));Tap("RegionJump_1");Tap("LevelSlot_1_0");Add(()=>Check(W.InformationVisible&&UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="LevelMap","Missing future level cannot launch"));Tap("MapInfoClose");Tap("MapHome");Tap("NavMap");Add(()=>Check(W!=null&&W.Progression.RegionComplete(0),"Home map navigation opens connected map"));Tap("LevelSlot_0_0");Tap("Pause");Tap("PauseHome");Add(()=>Check(W!=null&&!UnityEngine.Object.FindFirstObjectByType<PrototypeApp>(),"Pause return respects map origin"));
  SessionState.SetBool("MapProgressionTest",true);EditorSceneManager.OpenScene("Assets/Scenes/LevelMap.unity");EditorApplication.isPlaying=true;next=EditorApplication.timeSinceStartup+2;
 }
 [Serializable]class Result{public bool success;public string error;public int count;public string[] checks;}
 static void Finish(string error){SessionState.SetBool("MapProgressionTest",false);bool same=PlayerPrefs.HasKey(GameplayProgress.StorageKey)==hadOriginal&&PlayerPrefs.GetString(GameplayProgress.StorageKey,"")==original;if(!same)error=(error??"")+" Real player storage changed";else checks.Add("Real player save untouched");File.WriteAllText("docs/PART06B_TEST_RESULTS.json",JsonUtility.ToJson(new Result{success=error==null,error=error,count=checks.Count,checks=checks.ToArray()},true));EditorApplication.isPlaying=false;GameplayProgress.RestorePlayerProfile();GameplayLevelCatalog.ResetSelection();}
 static void Tick(){if(!SessionState.GetBool("MapProgressionTest",false)||!EditorApplication.isPlaying||EditorApplication.timeSinceStartup<next)return;try{next=EditorApplication.timeSinceStartup+1.15;if(actions.Count==0){Finish(null);return;}actions.Dequeue()();}catch(Exception e){Finish(e.ToString());}}
}
